s=s.replace(old,new,1)
s=s.replace('''"near_look": 0, "near_look_miss": 0, "look_on": 0, "look_on_miss": 0, "kept": 0}''','''"near_look": 0, "near_look_miss": 0, "look_on": 0, "look_on_miss": 0, "kept": 0, "graze": 0}''',1)
s=s.replace('''"near_look_miss", "look_on", "look_on_miss", "kept"]:''','''"near_look_miss", "look_on", "look_on_miss", "kept", "graze"]:''',1)
s=s.replace('''silent_noeffect=%d empty_pieces=%d" % [
		total.cases, total.overlap, total.contact, total.miss, total.gap_over, gap_max * 1e3, total.silent, total.empty_pieces])''','''silent_noeffect=%d empty_pieces=%d grazes_only=%d" % [
		total.cases, total.overlap, total.contact, total.miss, total.gap_over, gap_max * 1e3, total.silent, total.empty_pieces, total.graze])''',1)

# oracle function
a=s.index("# The first arc angle (rad, from START_DEG down)")
b=s.index("static func _dist(")
new='''# The swept head against the board's wood: {th: the first arc angle (rad, from START_DEG down) where the head holds V_MIN of
# wood (INF: never), graze: it touched wood but never V_MIN}.
func _first_overlap(sw: Dictionary, box: AABB, solid: Callable) -> Dictionary:
	var R := float(sw.radius)
	var edge := float(sw.edge)
	var deep := float(sw.deep)
	var ta := tan(float(sw.half))
	var cone := String(sw.get("profile", "wedge")) == "cone"
	var local := PackedVector3Array()         # (a along the edge, z behind it, b across)
	var weight := PackedFloat64Array()        # m3 each point stands for
	var rb := 0.0
	var z := 0.0
	while z <= deep + 1e-9:
		var h := AxeSwing.cheek(sw, z)
		var ea := 0.5 * edge + (z * ta if cone else 0.0)
		var bs := [0.0] if h < 1e-6 else [-h, -0.5 * h, 0.0, 0.5 * h, h]
		var a := -ea
		while a <= ea + 1e-9:
			for b: float in bs:
				local.append(Vector3(a, z, b))
				weight.append(GRID * GRID * (0.5 * h if h >= 1e-6 else 0.0))
				rb = maxf(rb, sqrt(a * a + z * z + b * b))
			a += GRID
		z += GRID
	rb += 0.004
	var th := deg_to_rad(AxeSwing.START_DEG)
	var th_end := deg_to_rad(AxeSwing.END_DEG)
	var s: Vector3 = sw.s
	var tip := R + 0.5 * edge
	var dth := STEP / tip
	var touched := false
	var w: Vector3 = sw.w
	while th > th_end:
		var n := AxeSwing.n_at(sw, th)
		var t := AxeSwing.t_at(sw, th)
		var mid := s + n * R
		var d := _dist(box, mid)
		if d > rb:
			th -= maxf((d - rb) / R, dth)
			continue
		var vol := 0.0
		for i in local.size():
			var lp := local[i]
			var p := mid + n * lp.x - t * lp.y + w * lp.z
			if box.has_point(p) and solid.call(p):
				touched = true
				vol += weight[i]
		if vol >= V_MIN:
			return {"th": th, "graze": false}
		th -= dth
	return {"th": INF, "graze": touched}


'''
s=s[:a]+new+s[b:]
open(p,'w').write(s)
EOF
