# «далеко». The four side rays (LOOK_THICK off) only ask the stones; the answer's point is the depth along the look.
func _ray_thick(eye: Vector3, dir: Vector3, reach: float) -> Dictionary:
	var best := _ray_aim(eye, dir, reach, false)
	if Tools.legacy_feel:
		return best
	var rocks := get_tree().get_first_node_in_group("rock_system")
	var bd := eye.distance_to(best.point) if best.has("point") else reach
	var u := dir.cross(Vector3.UP)
	u = u.normalized() if u.length() > 1e-3 else Vector3.RIGHT
	var v := u.cross(dir).normalized()
	for off: Vector3 in [u, -u, v, -v]:
		var from := eye + off * ChopAim.LOOK_THICK
		for hit: Dictionary in [_tagged(rocks.aim(from, dir, bd) if rocks else {}, "rock"), _piece_aim(from, dir, bd, false)]:
			if hit.has("point"):
				var t := (hit.point as Vector3 - eye).dot(dir)
				if t < bd:
					bd = t
					best = {"point": eye + dir * t, "target": hit.get("target", "")}
	return best


'''
