# --- the remaining wood's surface (task 62 feel1: the item panel's chip shows every cut) ----------------

## Triangles (a soup, wood frame, front faces clockwise seen from outside) of the boundary of the wood the cells hold in
## slices i0..i1-1: every face between a wood cell and an air cell (or the end of the range), greedy-merged into
## rectangles. Closed, and exactly the cells' volume (cell_volume() x the cells). Empty when over `max_cells` (a huge log).
func surface(i0: int, i1: int, max_cells := 4000000) -> PackedVector3Array:
	var soup := PackedVector3Array()
	i0 = maxi(i0, 0)
	i1 = mini(i1, slices)
	if i1 <= i0 or (i1 - i0) * n * n > max_cells:
		return soup
	var ny := i1 - i0
	var sx := n + 2                      # x: columns, y: slices, z: rows; one cell of air round the block
	var sz := n + 2
	var occ := PackedByteArray()
	occ.resize(sx * sz * (ny + 2))
	var any := false
	for j in ny:
		var i := i0 + j
		var bits := _fine.get(i, PackedInt64Array()) as PackedInt64Array
		var y := slice_y(i)
		for row in n:
			var base := ((j + 1) * sz + row + 1) * sx + 1
			var z := -r_max + (row + 0.5) * cell
			for c in n:
				var on := false
				if bits.is_empty():
					on = solid(Vector3(-r_max + (c + 0.5) * cell, y, z))
				else:
					on = (bits[row * wpr + (c >> 6)] >> (c & 63)) & 1 == 1
				if on:
					occ[base + c] = 1
					any = true
	if not any:
		return soup
	var dim := [sx, ny + 2, sz]
	var stride := [1, sx * sz, sx]       # index step along x, y, z
	var org := Vector3(-r_max - cell, y0 + (i0 - 1) * DZ, -r_max - cell)   # of the padded block's corner
	var size := Vector3(cell, DZ, cell)
	for a in 3:
		var u := (a + 1) % 3
		var v := (a + 2) % 3
		for s in [-1, 1]:
			for k in range(1, dim[a] - 1):
				# the mask of faces on the plane between layer k and k + s: wood in k, air in k + s
				var mask := PackedByteArray()
				mask.resize(dim[u] * dim[v])
				for q in range(1, dim[v] - 1):
					for p in range(1, dim[u] - 1):
						var at: int = k * stride[a] + p * stride[u] + q * stride[v]
						if occ[at] == 1 and occ[at + s * stride[a]] == 0:
							mask[q * dim[u] + p] = 1
				for q in range(1, dim[v] - 1):
					var p := 1
					while p < dim[u] - 1:
						if mask[q * dim[u] + p] == 0:
							p += 1
							continue
						var w := 1
						while p + w < dim[u] - 1 and mask[q * dim[u] + p + w] == 1:
							w += 1
						var h := 1
						var grow := true
						while grow and q + h < dim[v] - 1:
							for t in w:
								if mask[(q + h) * dim[u] + p + t] == 0:
									grow = false
									break
							if grow:
								h += 1
						for r in h:
							for t in w:
								mask[(q + r) * dim[u] + p + t] = 0
