# A U-block: a profile in (x, y) extruded along z by t: the slot is `g` wide and `d` deep from the top.
func _ublock(w: float, h: float, g: float, d: float, t: float) -> CpuMesh:
	var poly := PackedVector2Array([Vector2(-w * 0.5, 0), Vector2(w * 0.5, 0), Vector2(w * 0.5, h), Vector2(g * 0.5, h), Vector2(g * 0.5, h - d),
		Vector2(-g * 0.5, h - d), Vector2(-g * 0.5, h), Vector2(-w * 0.5, h)])
