func _extrude(poly: PackedVector2Array, t: float) -> CpuMesh:
	var v := PackedVector3Array()
	var n := poly.size()
	for i in n:
		var a := poly[i]
		var b := poly[(i + 1) % n]
		var e := b - a
		var out := Vector3(e.y, -e.x, 0.0).normalized()           # (outward for a counter-clockwise profile; flipped below)
		NeckTest._quad(v, Vector3(a.x, a.y, -t * 0.5), Vector3(b.x, b.y, -t * 0.5), Vector3(b.x, b.y, t * 0.5), Vector3(a.x, a.y, t * 0.5), out)
	var idx := Geometry2D.triangulate_polygon(poly)
	for k in 2:
		var z := t * 0.5 if k == 0 else -t * 0.5
		var dir := Vector3.BACK if k == 0 else Vector3.FORWARD
		for i in range(0, idx.size(), 3):
			var tri := [Vector3(poly[idx[i]].x, poly[idx[i]].y, z), Vector3(poly[idx[i + 1]].x, poly[idx[i + 1]].y, z), Vector3(poly[idx[i + 2]].x, poly[idx[i + 2]].y, z)]
			var nn: Vector3 = -(tri[1] - tri[0]).cross(tri[2] - tri[0])
			if nn.dot(dir) >= 0.0:
				v.append_array(tri)
			else:
