# Item 18: the dig layer's mesh data after digs at late game time. Same metric as ageing_test AGE_EDGE (a triangle with a
# loose vertex: UV.x may differ <= 60 s) split by tint (a granular bed's vertex) + a patch-seam metric: the vertex that two
# neighbouring patch meshes share must carry the same UV.x / COLOR / tint in both (else a square edge on the patch line).
func mesh_check(label: String) -> Dictionary:
	var tris := 0
	var jumps := 0
	var jumps_tint := 0
	var worst := 0.0
	var worst_at := Vector3.ZERO
	var seam := {}
	var seam_n := 0
	var seam_bad := 0
	var seam_worst := 0.0
	var seam_at := ""
	var n1 := DigLayer.N + 1
	for key​ in dig.view._meshes:
		var mi: MeshInstance3D = dig.view._meshes[key​]
		var arr: Array = mi.mesh.surface_get_arrays(0)
		var cols: PackedColorArray = arr[Mesh.ARRAY_COLOR]
		var uv: PackedVector2Array = arr[Mesh.ARRAY_TEX_UV]
		var vs: PackedVector3Array = arr[Mesh.ARRAY_VERTEX]
		var idx: PackedInt32Array = arr[Mesh.ARRAY_INDEX]
		for v in n1 * n1:
			var k := Vector2i(roundi(vs[v].x * 100.0), roundi(vs[v].z * 100.0))
			var rec := [uv[v].x, cols[v].r, cols[v].g, cols[v].b, uv[v].y]
			if seam.has(k):
				seam_n += 1
				var o: Array = seam[k]
				var d := absf(o[0] - rec[0])
				var dc := maxf(absf(o[1] - rec[1]), maxf(absf(o[2] - rec[2]), absf(o[3] - rec[3])))
				if d > 0.5 or dc > 0.01 or absf(o[4] - rec[4]) > 0.5:
					seam_bad += 1
					if d > seam_worst:
						seam_worst = d
						seam_at = "%s %s vs %s" % [str(Vector2(k) / 100.0), str(o), str(rec)]
			else:
				seam[k] = rec
		for q in range(0, idx.size(), 3):
			var a := idx[q]
			var b := idx[q + 1]
			var c := idx[q + 2]
			if a >= n1 * n1 or b >= n1 * n1 or c >= n1 * n1:
				continue
			if cols[a].r <= 0.0 and cols[b].r <= 0.0 and cols[c].r <= 0.0:
				continue
			tris += 1
			var d := maxf(absf(uv[a].x - uv[b].x), maxf(absf(uv[b].x - uv[c].x), absf(uv[a].x - uv[c].x)))
			if d > worst:
				worst = d
				worst_at = vs[a]
			if d > EDGE_TOL:
				jumps += 1
				if uv[a].y > 0.0 or uv[b].y > 0.0 or uv[c].y > 0.0:
					jumps_tint += 1
	print("RG_MESH %s now=%.0f meshes=%d tris_with_earth=%d jumps=%d (with_tint=%d) worst_dUVx=%.1f at=%s | seam_pairs=%d seam_bad=%d seam_worst_dUVx=%.1f %s" % [label,
		TimeSystem.now, dig.view._meshes.size(), tris, jumps, jumps_tint, worst, str(worst_at), seam_n, seam_bad, seam_worst, seam_at])
	return {jumps = jumps, jumps_tint = jumps_tint, tris = tris, seam_bad = seam_bad}


